  `Pay_Method_Name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `branchs_id` bigint unsigned NOT NULL,
  `note` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '-',
  `currentblance` double(20,2) NOT NULL DEFAULT '0.00',
  `attachments` text COLLATE utf8mb4_unicode_ci,
  `orginal_type` int NOT NULL DEFAULT '0',
  `orginal_id` int DEFAULT NULL,
  `dely_record` bigint NOT NULL DEFAULT '0',
  `debtor` double(8,2) NOT NULL DEFAULT '0.00',
  `creditor` double(8,2) NOT NULL DEFAULT '0.00',
  `vat` int NOT NULL DEFAULT '0',
  `name` text COLLATE utf8mb4_unicode_ci,
  `tax` text COLLATE utf8mb4_unicode_ci,
  `decument_id` int NOT NULL DEFAULT '0',
  `type_decument` int NOT NULL DEFAULT '1',
  `save` int NOT NULL DEFAULT '1',
  `parent_dely_record` bigint DEFAULT NULL,
