  UNIQUE KEY `failed_jobs_uuid_unique` (`uuid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



CREATE TABLE `financial_accounts` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(225) NOT NULL,
  `name_en` text,
  `account_type` int NOT NULL,
  `is_parent` tinyint(1) NOT NULL DEFAULT '0',
  `parent_account_number` bigint DEFAULT NULL,
  `account_number` bigint NOT NULL,
  `start_balance_status` tinyint NOT NULL COMMENT 'e 1-credit -2 debit 3-balanced',
  `start_balance` decimal(10,2) NOT NULL COMMENT 'دائن او مدين او متزن اول المدة',
  `current_balance` decimal(15,2) NOT NULL DEFAULT '0.00',
  `other_table_FK` bigint DEFAULT NULL,
  `notes` varchar(225) DEFAULT NULL,
  `added_by` int NOT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'هل مفعل',
  `com_code` int NOT NULL,
  `date` date NOT NULL,
  `orginal_id` bigint DEFAULT NULL,
  `orginal_type` int DEFAULT NULL,
  `orginal_supplier` bigint DEFAULT NULL,
  `debtor_opening` double NOT NULL DEFAULT '0',
  `creditor_opening` double NOT NULL DEFAULT '0',
  `creditor_current` double(15,2) NOT NULL DEFAULT '0.00',
  `debtor_current` double(15,2) NOT NULL DEFAULT '0.00',
  `creditor_end` double NOT NULL DEFAULT '0',
  `debtor_end` double NOT NULL DEFAULT '0',
  `branchs_id` int DEFAULT NULL,
  `candidate_branch` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1242 DEFAULT CHARSET=utf8mb3 COMMENT='جدول الشجرة المحاسبية العامة';




CREATE TABLE `increaseـor_deduction_employees` (
