  `Number_of_Quantity` double NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `Pay` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Shabka',
  `branchs_id` bigint NOT NULL DEFAULT '1',
  `discount` decimal(8,2) NOT NULL DEFAULT '0.00',
  `discountOnInvoice` double NOT NULL DEFAULT '0',
  `discountOnProduct` double NOT NULL DEFAULT '0',
  `note` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '-',
  `status` int NOT NULL DEFAULT '0',
  `save` int NOT NULL DEFAULT '0',
  `cashamount` double(15,2) NOT NULL DEFAULT '0.00',
  `bankamount` double(15,2) NOT NULL DEFAULT '0.00',
  `creaditamount` double(15,2) NOT NULL DEFAULT '0.00',
  `morepayment_way` int NOT NULL DEFAULT '0',
  `Bank_transfer` double NOT NULL DEFAULT '0',
  `signing_time` datetime DEFAULT NULL,
  `xml` longtext COLLATE utf8mb4_unicode_ci,
  `document_type` enum('simplified','standard') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `invoice_type` enum('388','383','381') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sent_to_zatca` int NOT NULL DEFAULT '0',
  `sent_to_zatca_status` text COLLATE utf8mb4_unicode_ci,
  `invoiceUUid` text COLLATE utf8mb4_unicode_ci,
  `invoice_number` text COLLATE utf8mb4_unicode_ci,
  `invoice_counter` bigint DEFAULT NULL,
  `issue_time` time DEFAULT NULL,
  `issue_date` date DEFAULT NULL,
  `hash` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qr_zatca` text COLLATE utf8mb4_unicode_ci,
  `xmltags` text COLLATE utf8mb4_unicode_ci,
  `currentblance` double NOT NULL DEFAULT '0',
  `NOTICE_Number` bigint NOT NULL DEFAULT '0',
  `xmltags_return` text COLLATE utf8mb4_unicode_ci,
  `xml_return` text COLLATE utf8mb4_unicode_ci,
  `hash_return` text COLLATE utf8mb4_unicode_ci,
  `sent_to_zatca_status_return` text COLLATE utf8mb4_unicode_ci,
  `qr_zatca_return` text COLLATE utf8mb4_unicode_ci,
  `issue_date_return` date DEFAULT NULL,
  `issue_time_return` time DEFAULT NULL,
  `display_number` int NOT NULL DEFAULT '1',
  `payment_return` text COLLATE utf8mb4_unicode_ci,
  `clearedInvoice` longtext COLLATE utf8mb4_unicode_ci,
  `uuid` longtext COLLATE utf8mb4_unicode_ci,
  `p_o` text COLLATE utf8mb4_unicode_ci,
  `shippingfee` double NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `invoices_user_id_foreign` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5303 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



